function SingleProduct({ product }) {
    const router = useRouter();

    console.log("Product", product)

    const [productIndex, setProductIndex] = useState(0);
    const [productData, setProductData] = useState(product);

    return (
        <div>
            <div>
                <div>Name: {productData.name}</div>
                <div>Price: {productData.variations[productIndex].display_price}</div>

                <div>
                    {
                        productData.variations.map((object, index) =>
                            <button onClick={() => setProductIndex(index)} key={index} style={{ border: index === productIndex ? '3px solid red' : '', height: '50px', width: '50px', backgroundColor: `${object.attributes.attribute_pa_color}` }}></button>
                        )
                    }
                </div>
                <button height="50px">Add to cart</button>
            </div>

            {
                productData.variations[productIndex].variation_gallery_images.map((product, index) => {
                    return <img
                        src={product.url}
                        height="300px"
                        title="Contemplative Reptile"
                    />
                })
            }

        </div>
    )
}

export default SingleProduct;


SingleProduct.getInitialProps = async (ctx) => {

    const { query } = ctx;
    console.log("Query Single Product", WooCommerce.get('route').then(res => ({ p: res.data })))
    // return WooCommerce.get(`product/slug=${ctx.query['single-product']}`)
    return WooCommerce.get(`product/slug=${ctx.query['single-product']}/variations`)
        // return WooCommerce.get(`products/${ctx.query['single-product']}`)
        .then(response => ({ product: response.data }))
        .catch(error => ({ product: error.response.data }));
}

